$ErrorActionPreference='Stop'; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; Write-Host '=== INSTALANDO NODE.JS, NPM, NPX Y RDC ===' -ForegroundColor Cyan; if(!(Test-Path 'C:\Program Files\nodejs\node.exe')){$n=Invoke-RestMethod 'https://nodejs.org/dist/index.json'; $n=$n|Where-Object {$_.version -match '^v24\.' -and $_.files -contains 'win-x64-msi'}|Select-Object -First 1; if(!$n){throw 'No se encontró Node.js 24'}; $v=$n.version; $f="node-$v-x64.msi"; $p="$env:TEMP\$f"; Invoke-WebRequest "https://nodejs.org/dist/$v/$f" -OutFile $p -UseBasicParsing; if(!(Test-Path $p) -or (Get-Item $p).Length -lt 10000000){throw 'MSI incompleto'}; $i=Start-Process msiexec.exe -ArgumentList "/i `"$p`" /qn /norestart" -Wait -PassThru -Verb RunAs; if($i.ExitCode -notin @(0,3010)){throw "Error instalando Node.js: $($i.ExitCode)"}}; $env:Path="C:\Program Files\nodejs;$env:APPDATA\npm;$env:Path"; if(!(Test-Path 'C:\Program Files\nodejs\node.exe')){throw 'Node.js no instalado'}; if(!(Test-Path 'C:\Program Files\nodejs\npm.cmd')){throw 'NPM no instalado'}; if(!(Test-Path 'C:\Program Files\nodejs\npx.cmd')){throw 'NPX no instalado'}; Write-Host 'NODE:' -ForegroundColor Green; & 'C:\Program Files\nodejs\node.exe' --version; Write-Host 'NPM:' -ForegroundColor Green; & 'C:\Program Files\nodejs\npm.cmd' --version; Write-Host 'NPX:' -ForegroundColor Green; & 'C:\Program Files\nodejs\npx.cmd' --version; Write-Host '=== INICIANDO REMOTE DESKTOP COMMANDER ===' -ForegroundColor Cyan; & 'C:\Program Files\nodejs\npx.cmd' --yes @wonderwhy-er/desktop-commander@latest remote